action.mutation:
mutation UpdateApprovedWorkcenter($payload: [ApprovedWorkcenterUpdatePayloadInput!]!) {
  mutation: updateApprovedWorkcenter(payload: $payload) { 
    id
    partNoRevision
  }
}

mutation DeleteApprovedWorkcenter($payload: [ApprovedWorkcenterDeletePayloadInput!]!) {
  mutation: deleteApprovedWorkcenter(payload: $payload) { 
    id
    productNoRevision
  }
}
